style.css:
@-moz-document domain("roblox.com") {
/* Hide the original "Charts" text */
  a.charts-rename-exp-treatment[href="/charts"] {
    color: transparent !important;
    position: relative;
  }

  /* Add "Games" instead with better alignment */
  a.charts-rename-exp-treatment[href="/charts"]::after {
    content: "Games";
    color: white !important; /* Match Roblox's text color */
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%); /* Centers the text */
    width: 100%;
    text-align: center;
  }
}
